-- 📚 꼭집 주거 사전 — 배점·가점 항목 · 매입·국민 중심 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 5.6초 · 결과:
-- {"anns": 97, "by_std": {"SH 고유": 2, "국민임대": 29, "매입임대": 54, "영구임대": 9, "행복주택": 2, "행복주택(신혼희망)": 1}, "거주기간": 25, "거주기간_ex": ["SH_310653", "SH_310650", "2015122300020818"], "부양가족": 18, "부양가족_ex": ["2015122300020792", "2015122300020788", "2015122300020783"], "납입횟수": 73, "납입횟수_ex": ["SH_310653", "SH_310650", "21390_부산광역시_사하구"], "미성년자녀": 44, "미성년자녀_ex": ["SH_310653", "SH_310650", "2015122300020840"], "65세직계존속": 58, "65세직계존속_ex": ["SH_310653", "SH_310650", "21390_부산광역시_사하구"], "수급자": 34, "수급자_ex": ["2015122300020840", "2015122300020816", "2015122300020815"], "장애인": 59, "장애인_ex": ["SH_311349", "SH_310653", "SH_310650"], "동점": 14, "동점_ex": ["2015122300020873", "2015122300020843", "2015122300020835"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='배점·가점'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='배점·가점' group by 1)q),'거주기간',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'(거주\s*기간|연속\s*거주|거주한\s*기간)[^.]{0,30}(점|배점)'),'거주기간_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'(거주\s*기간|연속\s*거주|거주한\s*기간)[^.]{0,30}(점|배점)' order by 1 desc limit 3)q),'부양가족',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'부양\s*가족'),'부양가족_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'부양\s*가족' order by 1 desc limit 3)q),'납입횟수',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'(납입\s*횟수|납입\s*인정\s*회차|청약\s*(저축|통장)[^.]{0,20}(회|점))'),'납입횟수_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'(납입\s*횟수|납입\s*인정\s*회차|청약\s*(저축|통장)[^.]{0,20}(회|점))' order by 1 desc limit 3)q),'미성년자녀',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'미성년\s*자녀'),'미성년자녀_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'미성년\s*자녀' order by 1 desc limit 3)q),'65세직계존속',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'65세\s*이상[^.]{0,20}직계\s*존속'),'65세직계존속_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'65세\s*이상[^.]{0,20}직계\s*존속' order by 1 desc limit 3)q),'수급자',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'(생계|의료)\s*급여\s*수급'),'수급자_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'(생계|의료)\s*급여\s*수급' order by 1 desc limit 3)q),'장애인',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'장애인'),'장애인_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'장애인' order by 1 desc limit 3)q),'동점',(select count(distinct announcement_id) from y where cls='배점·가점' and t~'(동점|동일\s*점수)[^.]{0,40}(추첨|전산)'),'동점_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='배점·가점' and t~'(동점|동일\s*점수)[^.]{0,40}(추첨|전산)' order by 1 desc limit 3)q))j;
